#!/usr/bin/python3
"""Fixed October schedule release. Owns two files and additive campaign tables only."""
import ast
import base64
import fcntl
import hashlib
import json
import os
import re
from pathlib import Path
import shlex
import sqlite3
import stat
import subprocess
import sys
import tempfile
import time as clock
import urllib.request
import urllib.error
from datetime import datetime, timedelta
from zoneinfo import ZoneInfo

APP = Path('/opt/bots/ege-blizko')
DB = APP / 'data/coreapp_webhooks.db'
STATE = Path('/var/lib/ege-october-close-20261026')
SERVICE = 'ege-blizko'
RELEASE = 'EGE-OCTOBER-CLOSE-20261026-REVIEWED'
PINS = {'76ab3666a6b62488f15b266dd6de2e4eeff4ec1635a84abb3cf7d8dd0b3f55a3': '2651b2512996ed9592fa8d4c109453b6857847496648a2db157839716b172a3d', 'dd4c39bdbc064d098e262e5fadffdff7dbf07646e437c39724bb1ea6d872598e': '868ad0ea360d104be302db5b0d32f903867f659a7140708386d26b9d7c2ac3f9'}
MODULE_HASH = 'a01d6545212e6ed817c895dc459fdcab563a517ae7829372b64ae9401a0af8c2'
MODULE = base64.b64decode('')
TRANSFORM_CODE = base64.b64decode('')
COURSE = '6a8c4641d6c9f299cf1387a6'


def digest(data):
    return hashlib.sha256(data).hexdigest()


def regular(path):
    if not stat.S_ISREG(path.lstat().st_mode):
        raise ValueError('NON_REGULAR_FILE')


def run(args):
    return subprocess.run(args,check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                          text=True,timeout=60).stdout.strip()


def transform(data):
    namespace = {'__name__':'isolated_patch'}
    exec(compile(TRANSFORM_CODE,'reviewed_patch','exec'),namespace)
    return namespace['transform'](data)


def module_namespace():
    if digest(MODULE) != MODULE_HASH:
        raise ValueError('MODULE_HASH_MISMATCH')
    compile(MODULE,'october_2026_close.py','exec')
    namespace = {'__name__':'isolated_october'}
    exec(compile(MODULE,'october_2026_close.py','exec'),namespace)
    return namespace


def config():
    values = dict()
    for field in shlex.split(run(['systemctl','show',SERVICE,'-p','Environment','--value'])):
        if '=' in field:
            key,value=field.split('=',1);values[key]=value
    path=APP/'runtime-vars.json'
    if path.exists():
        regular(path)
        values.update(json.loads(path.read_text()))
    if str(values.get('COREAPP_DB_PATH')) != str(DB):
        raise ValueError('DATABASE_CONFIGURATION_UNVERIFIED')
    chat=int(values.get('CHAT_ID') or 0)
    if chat>=0 or chat == -1004449482685:
        raise ValueError('EGE_CHAT_UNVERIFIED')
    thread=str(values.get('MESSAGE_THREAD_ID') or '')
    if thread and not thread.isdecimal():
        raise ValueError('THREAD_UNVERIFIED')
    return {'chat_id':str(chat),'thread_id':thread}


def atomic(path,data,metadata):
    fd,tmp=tempfile.mkstemp(prefix='.october-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(data);stream.flush()
            os.fchown(stream.fileno(),metadata['uid'],metadata['gid'])
            os.fchmod(stream.fileno(),metadata['mode']);os.fsync(stream.fileno())
        os.replace(tmp,path)
        fd=os.open(path.parent,os.O_RDONLY|os.O_DIRECTORY)
        try:os.fsync(fd)
        finally:os.close(fd)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)


def database_backup(name='database.sqlite'):
    destination=STATE/name
    if os.path.lexists(destination):
        raise ValueError('BACKUP_ALREADY_EXISTS')
    with sqlite3.connect(DB,timeout=30) as source:
        with sqlite3.connect(destination) as dest:
            source.backup(dest)
            if dest.execute('PRAGMA integrity_check').fetchone()[0]!='ok':
                raise ValueError('BACKUP_INTEGRITY_FAILED')
    os.chmod(destination,0o600)


def cohort():
    regular(DB)
    with sqlite3.connect(f'file:{DB}?mode=ro',uri=True) as conn:
        users={int(r[0]) for r in conn.execute('''SELECT telegram_user_id FROM students
            WHERE active=1 AND course_id=? AND telegram_user_id IS NOT NULL''',(COURSE,))}
        # Assignment history must exist; never guess eligibility from all public topics.
        if not conn.execute('SELECT 1 FROM ege11_trainer_assignment_periods LIMIT 1').fetchone():
            raise ValueError('ASSIGNMENT_HISTORY_MISSING')
    if len(users)!=13 or any(uid<=0 for uid in users):
        raise ValueError('EXPECTED_THIRTEEN_STUDENTS_CHANGED')
    return sorted(users)


def expected_config(namespace,settings):
    return {**settings,'enabled':'0','notice_at':namespace['NOTICE_AT'].isoformat(),
            'cutoff':namespace['CUTOFF'].isoformat(),'results_at':namespace['CLOSE_AT'].isoformat()}


def verify_cancelled_queue(conn,namespace,settings,users):
    current=dict(conn.execute('SELECT key,value FROM october_2026_config'))
    if current != expected_config(namespace,settings):
        raise ValueError('RETRY_CONFIGURATION_CHANGED')
    rows=conn.execute("SELECT kind,recipient_id,status,message_id FROM october_2026_deliveries WHERE campaign=?",
                      (namespace['NOTICE_KEY'],)).fetchall()
    expected={('course',int(settings['chat_id'])),*[('student',uid) for uid in users]}
    if (len(rows)!=14 or {(row[0],int(row[1])) for row in rows} != expected
            or any(row[2]!='cancelled' or row[3] is not None for row in rows)):
        raise ValueError('RETRY_QUEUE_HAS_DELIVERED_OR_AMBIGUOUS_MESSAGES')


def verify_retry(data,metadata,namespace,settings,users):
    info=STATE.lstat()
    if (not stat.S_ISDIR(info.st_mode) or info.st_uid!=os.geteuid()
            or stat.S_IMODE(info.st_mode)&0o077):
        raise ValueError('RETRY_STATE_DIRECTORY_UNTRUSTED')
    for name in ('original.py','metadata.json','database.sqlite'):
        path=STATE/name
        regular(path)
        info=path.stat()
        if info.st_uid!=os.geteuid() or stat.S_IMODE(info.st_mode)&0o077:
            raise ValueError('RETRY_BACKUP_PERMISSIONS_CHANGED')
    if ((STATE/'original.py').read_bytes()!=data
            or json.loads((STATE/'metadata.json').read_text())!=metadata):
        raise ValueError('RETRY_BACKUP_DOES_NOT_MATCH_RESTORED_SOURCE')
    with sqlite3.connect(f"file:{STATE/'database.sqlite'}?mode=ro",uri=True) as conn:
        if conn.execute('PRAGMA integrity_check').fetchone()[0]!='ok':
            raise ValueError('RETRY_BACKUP_INTEGRITY_FAILED')
    with sqlite3.connect(f'file:{DB}?mode=ro',uri=True) as conn:
        verify_cancelled_queue(conn,namespace,settings,users)


def prepare_queue(namespace,settings,users,retry=False):
    with sqlite3.connect(DB,timeout=30) as conn:
        conn.executescript(namespace['SCHEMA'])
        with conn:
            if retry:
                verify_cancelled_queue(conn,namespace,settings,users)
                changed=conn.execute("UPDATE october_2026_deliveries SET status='pending',updated_at=? WHERE campaign=? AND status='cancelled' AND message_id IS NULL",
                    (datetime.now(ZoneInfo('Europe/Moscow')).isoformat(),namespace['NOTICE_KEY'])).rowcount
                if changed!=14:
                    raise ValueError('RETRY_QUEUE_COUNT_CHANGED')
                return
            existing=dict(conn.execute('SELECT key,value FROM october_2026_config'))
            if existing:
                raise ValueError('EXISTING_CAMPAIGN_CONFIGURATION')
            conn.executemany('INSERT INTO october_2026_config VALUES(?,?)',expected_config(namespace,settings).items())
            for kind,recipient in [('course',int(settings['chat_id'])),*[( 'student',uid) for uid in users]]:
                conn.execute("INSERT INTO october_2026_deliveries (campaign,kind,recipient_id,status,updated_at) VALUES(?,?,?,'pending',?)",
                    (namespace['NOTICE_KEY'],kind,recipient,datetime.now(ZoneInfo('Europe/Moscow')).isoformat()))


def enable(value):
    with sqlite3.connect(DB,timeout=30) as conn:
        exists=conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='october_2026_config'").fetchone()
        if exists:
            conn.execute("UPDATE october_2026_config SET value=? WHERE key='enabled'",('1' if value else '0',))
            if not value:
                conn.execute("UPDATE october_2026_deliveries SET status='cancelled' WHERE status='pending'")


def fix_sidecar_permissions():
    info=DB.stat()
    for suffix in ('-wal','-shm'):
        path=Path(str(DB)+suffix)
        if path.exists():
            regular(path)
            os.chown(path,info.st_uid,info.st_gid)
            os.chmod(path,stat.S_IMODE(info.st_mode))


def restart():
    run(['systemctl','restart',SERVICE])


def healthy(since,marker=True):
    # Invocation IDs avoid timezone ambiguity and old startup messages.
    deadline=clock.monotonic()+120
    stable=0
    invocation=None
    state={'active':False,'http':0,'marker':not marker,'journal':not marker}
    while clock.monotonic()<deadline:
        state={'active':False,'http':0,'marker':not marker,'journal':not marker}
        try:
            state['active']=run(['systemctl','is-active',SERVICE])=='active'
            current=run(['systemctl','show',SERVICE,'-p','InvocationID','--value']) if marker else None
            if marker and not re.fullmatch(r'[0-9a-f]{32}',current):
                raise ValueError('INVALID_SERVICE_INVOCATION')
            if current!=invocation:
                stable=0
                invocation=current
            if marker:
                logs=run(['journalctl','-u',SERVICE,'_SYSTEMD_INVOCATION_ID='+current,'--no-pager','-o','cat'])
                state['journal']=True
                state['marker']=('October 2026 close ready:' in logs and 'Kulek rewards ready:' in logs)
            try:
                with urllib.request.urlopen('http://127.0.0.1:8080/health',timeout=3) as response:
                    state['http']=response.status
            except urllib.error.HTTPError as error:
                state['http']=int(error.code)
            if state['active'] and state['http']==200 and state['marker']:
                stable+=1
                if stable>=2:
                    return True
            else:
                stable=0
        except Exception:
            stable=0
        clock.sleep(2)
    print('OCTOBER_CLOSE_READINESS_FAILED '+json.dumps(state,sort_keys=True),flush=True)
    return False


def restore():
    regular(STATE/'original.py');regular(STATE/'metadata.json')
    data=(STATE/'original.py').read_bytes()
    if digest(data) not in PINS:
        raise ValueError('BACKUP_HASH_CHANGED')
    metadata=json.loads((STATE/'metadata.json').read_text())
    enable(False)
    fix_sidecar_permissions()
    atomic(APP/'kulek_rewards.py',data,metadata)
    module=APP/'october_2026_close.py'
    if module.exists():
        regular(module)
        if digest(module.read_bytes())!=MODULE_HASH:
            raise ValueError('MODULE_CHANGED_BEFORE_ROLLBACK')
        module.unlink()
    restart()
    if not healthy('now',marker=False):
        raise ValueError('ROLLBACK_HEALTH_FAILED')


def apply(rollback=False):
    target=APP/'kulek_rewards.py';module=APP/'october_2026_close.py'
    regular(target);data=target.read_bytes();current=digest(data)
    at=datetime.now(ZoneInfo('Europe/Moscow'))
    if rollback:
        # Original code would publish October early on November 1.
        if datetime(2026,11,1,tzinfo=at.tzinfo)<=at<datetime(2026,11,5,9,tzinfo=at.tzinfo):
            raise ValueError('ROLLBACK_WOULD_REENABLE_EARLY_OCTOBER_CLOSE')
        if current not in set(PINS.values()):
            raise ValueError('ROLLBACK_TARGET_CHANGED')
        restore();print('OCTOBER_CLOSE_ROLLBACK_OK_DATABASE_NOT_RESTORED');return
    if current in set(PINS.values()) and module.exists():
        regular(module)
        with sqlite3.connect(f'file:{DB}?mode=ro',uri=True) as conn:
            cfg=dict(conn.execute('SELECT key,value FROM october_2026_config'))
        if digest(module.read_bytes())==MODULE_HASH and cfg.get('enabled')=='1' and healthy('today'):
            print('OCTOBER_CLOSE_ALREADY_INSTALLED_NO_RESTART');return
        raise ValueError('PARTIAL_OR_UNHEALTHY_RELEASE')
    if at>=datetime(2026,10,27,19,tzinfo=at.tzinfo)-timedelta(minutes=5):
        raise ValueError('SCHEDULE_INSTALLATION_DEADLINE_PASSED')
    if current not in PINS or os.path.lexists(module):
        raise ValueError('PRODUCTION_VERSION_UNREVIEWED')
    if run(['systemctl','show',SERVICE,'-p','User','--value'])!='ege-bot':
        raise ValueError('SERVICE_USER_CHANGED')
    if run(['systemctl','is-active',SERVICE])!='active':
        raise ValueError('SERVICE_NOT_ACTIVE')
    namespace=module_namespace();settings=config();users=cohort()
    result=transform(data)
    if digest(result)!=PINS[current]:
        raise ValueError('PATCH_OUTPUT_UNREVIEWED')
    info=target.stat();metadata={'uid':info.st_uid,'gid':info.st_gid,'mode':stat.S_IMODE(info.st_mode)}
    retry=os.path.lexists(STATE)
    if retry:
        verify_retry(data,metadata,namespace,settings,users)
        database_backup('retry-'+str(clock.time_ns())+'-database.sqlite')
    else:
        STATE.mkdir(mode=0o700,exist_ok=False)
        atomic(STATE/'original.py',data,{'uid':0,'gid':0,'mode':0o600})
        atomic(STATE/'metadata.json',json.dumps(metadata).encode(),{'uid':0,'gid':0,'mode':0o600})
        database_backup()
    if target.read_bytes()!=data:
        raise ValueError('TARGET_CHANGED_DURING_BACKUP')
    since=datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        prepare_queue(namespace,settings,users,retry=retry)
        atomic(module,MODULE,{'uid':info.st_uid,'gid':info.st_gid,'mode':0o644})
        atomic(target,result,metadata)
        enable(True)
        fix_sidecar_permissions()
        restart()
        if not healthy(since):raise ValueError('HEALTH_OR_STARTUP_MARKER_MISSING')
        with sqlite3.connect(f'file:{DB}?mode=ro',uri=True) as conn:
            count=conn.execute("SELECT count(*) FROM october_2026_deliveries WHERE campaign=? AND status='pending'",(namespace['NOTICE_KEY'],)).fetchone()[0]
        if count!=14:raise ValueError('EXPECTED_FOURTEEN_QUEUED_MESSAGES_MISSING')
    except Exception:
        restore()
        print('OCTOBER_CLOSE_AUTO_ROLLBACK_OK_DATABASE_NOT_RESTORED')
        raise
    print('OCTOBER_CLOSE_RELEASE_OK_BACKUP_HEALTH_AND_14_MESSAGES_SCHEDULED')
    print('NOTICE_MSK=2026-10-27T19:00:00+03:00; DEADLINE_EXCLUSIVE=2026-11-05T00:00:00+03:00; RESULTS_MSK=2026-11-05T09:00:00+03:00')


if __name__=='__main__':
    try:
        if os.geteuid()!=0 or len(sys.argv)!=2 or sys.argv[1] not in (RELEASE,RELEASE+'-ROLLBACK'):
            raise ValueError('INVALID_ROOT_RELEASE_ACTION')
        os.umask(0o077)
        print('OCTOBER_CLOSE_HELPER_SHA256='+digest(Path(__file__).read_bytes()),flush=True)
        with open('/run/lock/ege-blizko-autodeploy.lock','a') as lock:
            fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
            apply(sys.argv[1].endswith('-ROLLBACK'))
    except Exception as error:
        message=str(error) if isinstance(error,ValueError) and str(error).isidentifier() else type(error).__name__
        print('OCTOBER_CLOSE_RELEASE_STOPPED: '+message)
        sys.exit(1)
